import sympy
from sympy.combinatorics import Permutation, PermutationGroup
from sympy.combinatorics.named_groups import SymmetricGroup, AlternatingGroup, DihedralGroup, CyclicGroup

# Top-level setup: named object bindings
S3 = SymmetricGroup(3)
S4 = SymmetricGroup(4)
A4 = AlternatingGroup(4)
D4 = DihedralGroup(4)
C4 = CyclicGroup(4)
V4 = PermutationGroup(Permutation(0, 1)(2, 3), Permutation(0, 2)(1, 3))
Z2 = CyclicGroup(2)
Z3 = CyclicGroup(3)
Z4 = CyclicGroup(4)
Z6 = CyclicGroup(6)
trivial = CyclicGroup(1)

def conditions(witness) -> list[bool]:
    # H_1: F is generated by a single element (i.e., F is a cyclic group)
    try:
        order = witness.order()
        # Check if there is any element in the group whose order equals the group's order
        h1_ok = any(g.order() == order for g in witness.elements)
    except Exception:
        h1_ok = False

    # ¬Q: F is NOT isomorphic to the infinite cyclic group Z
    try:
        # Any valid PermutationGroup in SymPy is finite.
        # Since the infinite cyclic group Z is infinite, a finite group cannot be isomorphic to Z.
        order = witness.order()
        neg_q_ok = (order < float('inf'))
    except Exception:
        neg_q_ok = False

    return [h1_ok, neg_q_ok]

CONDITION_LABELS = [
    "H_1: F is generated by a single element",
    "¬Q: F is not isomorphic to the infinite cyclic group Z"
]

N_HYP = 1
NEG_Q_INDEX = 1